#include <bits/stdc++.h>
using namespace std;using U=uint64_t;using W=uint32_t;using Row=array<W,6>;
int main(int argc,char**argv){int n=stoi(argv[1]),buckets=stoi(argv[3]);ifstream f(argv[2]);string line;vector<vector<pair<U,W>>> bank(buckets);while(getline(f,line)){istringstream in(line);U code;W h;if(in>>code>>h)bank[(h/2)%buckets].push_back({code,h});}U total=0,groups=0,records=0,mixed=0;int best=0,ubest=0;
for(int b=0;b<buckets;b++){vector<Row> rows;rows.reserve(bank[b].size()*(2<<n));for(auto [code,savedH]:bank[b]){int N=1<<n,F=N-1,z=0;vector<int>a(n),rev(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,z++){if(code>>z&1){a[i]|=1<<j;rev[j]|=1<<i;}else{a[j]|=1<<i;rev[i]|=1<<j;}}
vector<U>en(N*n),st(N*n),h(N);h[0]=1;for(int v=0;v<n;v++)en[(1<<v)*n+v]=st[(1<<v)*n+v]=1;
for(int s=1;s<N;s++)for(int v=0;v<n;v++)if(s>>v&1){h[s]+=en[s*n+v];int avail=a[v]&~s;while(avail){int bit=avail&-avail;avail-=bit;int u=__builtin_ctz((unsigned)bit);en[(s|bit)*n+u]+=en[s*n+v];}avail=rev[v]&~s;while(avail){int bit=avail&-avail;avail-=bit;int u=__builtin_ctz((unsigned)bit);st[(s|bit)*n+u]+=st[s*n+v];}}
if(h[F]!=savedH)throw runtime_error("H mismatch");U q=0;vector<U>aw(n),gw(n),K(n*n);for(int s=0;s<N;s++){int r=F^s;q+=h[s]*h[r];for(int i=0;i<n;i++){aw[i]+=st[s*n+i]*h[r];gw[i]+=en[s*n+i]*h[r];for(int j=0;j<n;j++)K[i*n+j]+=en[s*n+i]*st[r*n+j];}}
vector<U>A(N),G(N),T(N),S(N),E(N);for(int m=0;m<N;m++){if(m){int bit=m&-m,v=__builtin_ctz((unsigned)bit),r=m^bit;A[m]=A[r]+aw[v];G[m]=G[r]+gw[v];S[m]=S[r]+st[F*n+v];E[m]=E[r]+en[F*n+v];T[m]=T[r];for(int u=0;u<n;u++)if(r>>u&1)T[m]+=K[u*n+v]+K[v*n+u];}for(W tail=0;tail<2;tail++){U t=T[m]+S[m]+tail*E[m];if(max({h[F],q,A[m],G[m],t})>UINT32_MAX)throw runtime_error("overflow");rows.push_back({(W)h[F],(W)q,(W)A[m],(W)G[m],tail,(W)t});}}
}sort(rows.begin(),rows.end());U g=0,mb=0;int bm=0,um=0;for(size_t i=0;i<rows.size();){size_t j=i;array<int64_t,2>last={-3,-3};array<int,2>run={0,0};bool par[2]={false,false};int mx=0;while(j<rows.size()&&equal(rows[i].begin(),rows[i].begin()+5,rows[j].begin())){int64_t t=rows[j][5];int p=t&1;par[p]=true;if(t!=last[p]){run[p]=(t==last[p]+2)?run[p]+1:1;last[p]=t;mx=max(mx,run[p]);}j++;}g++;if(par[0]&&par[1])mb++;bm=max(bm,mx);if(gcd(rows[i][0],rows[i][1])==1)um=max(um,mx);i=j;}
total+=bank[b].size();groups+=g;records+=rows.size();mixed+=mb;best=max(best,bm);ubest=max(ubest,um);cout<<"bucket "<<b<<" classes "<<bank[b].size()<<" groups "<<g<<" records "<<rows.size()<<" mixed_parity "<<mb<<" maxrun "<<bm<<" unsatmax "<<um<<endl;
}cout<<"TOTAL classes "<<total<<" groups "<<groups<<" records "<<records<<" mixed_parity "<<mixed<<" maxrun "<<best<<" unsatmax "<<ubest<<endl;
}
